// Work out the reporting window and carry the Config values forward.
const cfg = $input.first().json;
const days = Number(cfg.days) || 7;
const until = new Date();
const since = new Date(until.getTime() - days * 24 * 60 * 60 * 1000);
return [{
  json: {
    ...cfg,
    since: since.toISOString(),
    sinceDate: since.toISOString().slice(0, 10),
    until: until.toISOString(),
    untilDate: until.toISOString().slice(0, 10),
  },
}];

// Collect the week's GitHub activity and build the Claude request body.
const d = $('Compute dates').first().json;
const CAP = 100;

// Commits: an empty week yields a placeholder item without a sha, so filter on it.
const commits = $('GitHub - Commits').all()
  .map((i) => i.json)
  .filter((c) => c && c.sha)
  .slice(0, CAP);
// Search API responses carry the results in json.items.
const fromSearch = (name) => $(name).all()
  .flatMap((i) => (i.json && Array.isArray(i.json.items) ? i.json.items : []))
  .slice(0, CAP);
const issues = fromSearch('GitHub - Closed issues');
const prs = fromSearch('GitHub - Merged PRs');

const commitLines = commits.map((c) => {
  const msg = String((c.commit && c.commit.message) || '').split('\n')[0];
  const author = (c.commit && c.commit.author && c.commit.author.name) || (c.author && c.author.login) || 'unknown';
  return '- ' + c.sha.slice(0, 7) + ' ' + msg + ' (' + author + ')';
});
const itemLines = (list) => list.map((i) => '- #' + i.number + ' ' + i.title + ' (@' + ((i.user && i.user.login) || 'unknown') + ') ' + i.html_url);

const language = String(d.language || 'EN').trim().toUpperCase() === 'FR' ? 'French' : 'English';

const system = [
  'You write the weekly development summary for a software team.',
  'Write a narrative summary in ' + language + ': a few short paragraphs, then a short list of highlights.',
  'Only use the data provided. Do not invent facts, names or numbers.',
  'If there was no activity, say so in one sentence.',
  'Keep the whole answer under about 1500 characters. Plain text or light Markdown only.',
].join(' ');

const user = [
  'Repository: ' + d.github_repo,
  'Period: ' + d.sinceDate + ' to ' + d.untilDate,
  '',
  'Commits (' + commits.length + '):',
  commitLines.join('\n') || '(none)',
  '',
  'Closed issues (' + issues.length + '):',
  itemLines(issues).join('\n') || '(none)',
  '',
  'Merged pull requests (' + prs.length + '):',
  itemLines(prs).join('\n') || '(none)',
].join('\n');

return [{
  json: {
    body: {
      model: d.claude_model || 'claude-sonnet-4-20250514',
      max_tokens: 1024,
      system,
      messages: [{ role: 'user', content: user }],
    },
  },
}];

// Turn Claude's reply into a message that fits Discord (2000 chars) and Slack.
const d = $('Compute dates').first().json;
const res = $input.first().json;
const summary = (res.content || [])
  .filter((b) => b.type === 'text')
  .map((b) => b.text)
  .join('\n')
  .trim();
if (!summary) {
  throw new Error('Claude returned no text: ' + JSON.stringify(res).slice(0, 300));
}
const header = 'Weekly dev summary - ' + d.github_repo + ' (' + d.sinceDate + ' to ' + d.untilDate + ')';
let message = header + '\n\n' + summary;
if (message.length > 1900) {
  message = message.slice(0, 1897) + '...';
}
// Discord reads the content field, Slack reads the text field; each ignores the other.
return [{ json: { content: message, text: message } }];
